{"source":"import math

def predict(config):
    g = config.get
    ch = str(g("conv_channels", "128,256,576")).split(",")
    try:
        c1, c2, c3 = [float(x) for x in ch[:3]]
    except Exception:
        c1, c2, c3 = 128.0, 256.0, 576.0
    bs = float(g("batch_size", 1024) or 1024)
    ep = float(g("epochs", 10) or 10)
    steps = g("train_steps", None)
    if not steps:
        steps = ep * 50000.0 / bs
    steps = float(steps)
    lf = g("low_res_step_fraction", 0) or 0
    lf = float(lf)
    phases = g("num_resolution_phases", 0) or 0
    if lf > 0 and phases == 3:
        rf = (0.5625 + 0.766 + 1.0) / 3.0
    elif lf > 0:
        rf = lf * 0.5625 + (1 - lf)
    else:
        rf = 1.0
    F = (1024 * 9 * (24 * c1 + 2 * c1 * c1) + 256 * 9 * (c1 * c2 + 2 * c2 * c2)
         + 64 * 9 * (c2 * c3 + 2 * c3 * c3))
    opt = str(g("optimizer", "sgd_lookahead_ema"))
    mu = 0.0
    if "muon_conv" in opt:
        mu = 0.0008
    elif "muon" in opt:
        mu = 0.002 if opt.startswith("sgd") else 0.0015
    step = 0.002 + mu + (bs / 1024.0) * (0.0034 + 7.9e-12 * F * rf)
    t = 0.95 * step * steps

    params = float(g("num_params_approx", 2.0e6) or 2.0e6)
    aug = str(g("augmentation", "alternating_flip+translate2"))
    acc = 0.7567 + 0.07 * math.log(max(ep, 1.0) / 11.0) + 0.018 * math.log(params / 2.0e6)
    acc -= 0.036 * lf * lf
    if "cutout" in aug:
        acc -= 0.009
    if "translate4" in aug:
        acc -= 0.0035
    if "random_flip" in aug:
        acc -= 0.004
    ls = float(g("label_smoothing", 0.1) or 0.0)
    acc -= 0.03 * abs(ls - 0.1)
    if "muon_conv" in opt:
        acc += 0.012
    elif "muon" in opt:
        acc += 0.008
    acc -= 0.0005 * math.log(bs / 1024.0, 2)
    return {"time": t, "accuracy": acc}
","mechanisms":"Time is steps times per-step cost: a small fixed per-step overhead plus per-image conv FLOPs (block widths at 32/16/8 resolution) scaled by batch size, with low-resolution phases cutting FLOPs, and Muon adding a little per step. Accuracy rises with log epochs and log parameters. It falls with low-res fraction (quadratic), cutout, translate4, random flip and label smoothing away from 0.1. Muon on conv layers adds about 1%."}
